<?php
session_start();$configFile=dirname(__DIR__).'/config.php';$configured=file_exists($configFile);$c=$configured?require $configFile:[];$error='';
if(isset($_GET['logout'])){session_destroy();header('Location: index.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['login'])){if($configured&&hash_equals($c['admin_user'],$_POST['username']??'')&&password_verify($_POST['password']??'',$c['admin_password_hash'])){session_regenerate_id(true);$_SESSION['admin']=true;header('Location: index.php');exit;}$error='Incorrect username or password.';}
$logged=!empty($_SESSION['admin']);
function db($c){return new PDO("mysql:host={$c['db_host']};dbname={$c['db_name']};charset=utf8mb4",$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);}
if($logged&&$_SERVER['REQUEST_METHOD']==='POST'&&isset($_FILES['photo'])){try{$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$f=$_FILES['photo'];if($f['error']!==UPLOAD_ERR_OK||$f['size']>8*1024*1024)throw new Exception('Upload must be under 8 MB.');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!isset($allowed[$mime]))throw new Exception('Please upload JPG, PNG or WebP.');$dir=dirname(__DIR__).'/uploads/gallery';if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(12)).'.'.$allowed[$mime];if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$name))throw new Exception('Upload failed.');$pdo=db($c);$s=$pdo->prepare('INSERT INTO gallery(title,category,image_url) VALUES(?,?,?)');$s->execute([trim($_POST['title']??''),$_POST['category']??'Fellowship','uploads/gallery/'.$name]);header('Location: index.php?uploaded=1');exit;}catch(Throwable $e){$error=$e->getMessage();}}
if($logged&&isset($_POST['delete'])){try{$pdo=db($c);$s=$pdo->prepare('SELECT image_url FROM gallery WHERE id=?');$s->execute([(int)$_POST['delete']]);$p=$s->fetchColumn();$d=$pdo->prepare('DELETE FROM gallery WHERE id=?');$d->execute([(int)$_POST['delete']]);if($p&&str_starts_with($p,'uploads/gallery/'))@unlink(dirname(__DIR__).'/'.$p);header('Location: index.php');exit;}catch(Throwable $e){$error='Could not delete photo.';}}
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Adonai Admin</title><style>body{font-family:Arial;background:#f2f6f9;color:#0b2e52;margin:0}.wrap{max-width:900px;margin:50px auto;padding:20px}.box{background:white;padding:30px;box-shadow:0 10px 40px #002b5015;margin-bottom:20px}input,select{width:100%;padding:12px;margin:7px 0 17px;box-sizing:border-box;border:1px solid #cad8e3}button,.button{background:#063966;color:white;padding:12px 18px;border:0;text-decoration:none;cursor:pointer}.danger{background:#9f2731}.top{display:flex;justify-content:space-between;align-items:center}.photo{display:grid;grid-template-columns:90px 1fr auto;gap:15px;align-items:center;border-top:1px solid #ddd;padding:12px 0}.photo img{width:90px;height:65px;object-fit:cover}.error{color:#a11}.ok{color:#18713c}</style></head><body><div class="wrap"><?php if(!$configured):?><div class="box"><h1>Setup required</h1><p>Create <code>config.php</code> from <code>config.example.php</code> and add your Crazy Domains MySQL credentials and admin password hash.</p></div><?php elseif(!$logged):?><div class="box" style="max-width:420px;margin:auto"><h1>Adonai Admin</h1><p>Sign in to manage the church gallery.</p><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif?><form method="post"><input type="hidden" name="login" value="1"><label>Username</label><input name="username" required><label>Password</label><input name="password" type="password" required><button>Sign in</button></form></div><?php else:?><div class="top"><div><h1>Gallery Manager</h1><p>Upload and manage website gallery photos.</p></div><a class="button" href="?logout=1">Sign out</a></div><?php if(isset($_GET['uploaded'])):?><p class="ok">Photo published successfully.</p><?php endif?><?php if($error):?><p class="error"><?=htmlspecialchars($error)?></p><?php endif?><div class="box"><h2>Add photo</h2><form method="post" enctype="multipart/form-data"><label>Photo</label><input type="file" name="photo" accept="image/jpeg,image/png,image/webp" required><label>Title</label><input name="title" maxlength="150"><label>Category</label><select name="category"><option>Worship</option><option>Sunday School</option><option>ACYM</option><option>VBS</option><option>Kids Camp</option><option>Fellowship</option><option>Events</option></select><button>Publish photo</button></form></div><div class="box"><h2>Published photos</h2><?php try{$photos=db($c)->query('SELECT * FROM gallery ORDER BY created_at DESC')->fetchAll(PDO::FETCH_ASSOC);}catch(Throwable $e){$photos=[];}foreach($photos as $p):?><div class="photo"><img src="../<?=htmlspecialchars($p['image_url'])?>"><div><b><?=htmlspecialchars($p['title']?:$p['category'])?></b><br><small><?=htmlspecialchars($p['category'])?></small></div><form method="post" onsubmit="return confirm('Delete this photo?')"><button class="danger" name="delete" value="<?=$p['id']?>">Delete</button></form></div><?php endforeach;if(!$photos):?><p>No photos uploaded yet.</p><?php endif?></div><?php endif?></div></body></html>